import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.server.ResponseStatusException;

@RestController
@RequestMapping("/api/people")
public class PersonController {

    public record PersonView(Long id, String name, Integer alpha, Integer beta, Integer gamma, Integer delta, Integer epsilon, Integer zeta,
            Grade grade, Integer weight, Kind kind, Integer verge, Integer thrust, Integer drift, Integer momentum, Integer force, Integer sway, Integer torque, Integer pivot, Integer blend, Integer flux, Integer crest, Integer swing, Integer haul, Integer vector, String phase, Integer load, String tier, List<PatronView> patrons,
            Integer backing, Integer net, Integer rank, Integer percentile, LocalDate onset, Long age, Long decay, boolean active, Integer effective,
            Integer clout, Integer influence, Integer brace, Integer tide, Integer strain, String pulse, List<String> regions, Integer reach, Integer gust, Integer coil,
            List<PatronView> allies, int allyCount, Integer synergy, Integer combined, Integer score, int noteSum, Integer quality, Integer adjusted, String band, Integer scaled, Integer thrum, Integer spool, String drag, Integer lift, Integer yield, Integer grip, Integer charge, Integer churn, Integer norm, boolean outlier, State state, Integer ebb) {
        static PersonView of(Person p, Map<Long, Integer> ranks, Integer medianScaled, Integer medianBlend, LocalDate anchor) {
            Integer rank = ranks.get(p.getLocalId());
            return new PersonView(p.getLocalId(), p.getName(), p.getAlpha(), p.getBeta(), p.getGamma(), p.getDelta(), p.getEpsilon(), p.getZeta(),
                    p.getGrade(), p.getWeight(), p.getKind(), p.getVerge(), p.getThrust(), p.getDrift(), p.getMomentum(), p.getForce(), p.getSway(), p.getTorque(), p.getPivot(), p.getBlend(), p.getFlux(), p.getCrest(), p.getSwing(), p.getHaul(), p.getVector(), p.getPhase(), p.getLoad(), p.getTier(),
                    p.getPatrons().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getBacking(), p.getNet(), rank, PersonController.percentile(rank, ranks.size()), p.getOnset(),
                    p.getAge(anchor), p.getDecay(anchor), p.isActive(), p.getEffective(), p.getClout(),
                    p.getInfluence(), p.getBrace(), p.getTide(), p.getStrain(), p.getPulse(), p.getRegions(), p.getReach(), p.getGust(), p.getCoil(),
                    p.getAllies().stream().map(o -> new PatronView(o.getLocalId(), o.getName())).toList(),
                    p.getAllies().size(), p.getSynergy(), p.getCombined(), p.getScore(), p.getNoteSum(), p.getQuality(), p.getAdjusted(), p.getBand(), p.getScaled(), p.getThrum(), p.getSpool(), p.getDrag(), p.getLift(), p.getYield(), p.getGrip(), p.getCharge(), p.getChurn(),
                    PersonController.norm(p.getScaled(), medianScaled),
                    PersonController.outlier(PersonController.norm(p.getScaled(), medianScaled)), p.getState(),
                    PersonController.ebb(p.getBlend(), medianBlend));
        }
    }

    /**
     * A rank as a percentile of the ranked people: the best 100, the worst 0, evenly spread between
     * by rank and rounded to a whole number. A lone ranked person is 100; unranked has none.
     */
    static Integer percentile(Integer rank, int ranked) {
        if (rank == null) {
            return null;
        }
        if (ranked <= 1) {
            return 100;
        }
        return (int) Math.round((ranked - rank) * 100.0 / (ranked - 1));
    }

    /** Norm is scaled minus the sheet's median scaled; absent while either is absent. */
    static Integer norm(Integer scaled, Integer medianScaled) {
        return scaled == null || medianScaled == null ? null : scaled - medianScaled;
    }

    /** Ebb is blend minus the sheet's median blend; absent while either is absent. */
    static Integer ebb(Integer blend, Integer medianBlend) {
        return blend == null || medianBlend == null ? null : blend - medianBlend;
    }

    /** An outlier has a norm more than 100 away from zero in either direction; without a norm, not an outlier. */
    static boolean outlier(Integer norm) {
        return norm != null && Math.abs(norm) > 100;
    }

    /**
     * The median scaled of the people whose scaled can be worked out; for an even count, the lower of
     * the two middle values. Absent when there are none.
     */
// Their grip is their yield minus their coil ("n/a" while either is "n/a").
// Their charge is their vector plus their yield ("n/a" while either is "n/a").
// Their churn is their tide minus their vector ("n/a" while either is "n/a").
// The sheet's top charge is the name of the person with the highest charge, ties going to the name
// that comes first alphabetically ("n/a" when nobody has a charge).
// The sheet's total yield is everyone's yield added together, leaving out anyone whose yield is "n/a".
// Their norm is their scaled minus the median scaled of everyone on the sheet whose scaled can be
// worked out; for an even count, the lower of the two middle values ("n/a" while their scaled is "n/a").
// They are an outlier ("yes") when their norm is more than 100 away from zero in either direction, and
// otherwise "no" (also "no" while their norm is "n/a").
// The sheet's outlier count is how many of its people are outliers.
// Their ebb is their blend minus the median blend of everyone on the sheet whose blend can be worked
// out; for an even count, the lower of the two middle values ("n/a" while their blend is "n/a").
// The sheet's final total is the sum of the scaled of its people whose state is FINAL, counting
// "n/a" as zero.
// The sheet's band counts show how many of its people are in each band, A through E (zero when none
// are); people whose band is "n/a" are not counted.
// The sheet's drag counts show how many of its people are in each drag level, L0 through L3 (zero when
// none are); people whose drag is "n/a" are not counted.
// The sheet's pulse counts show how many of its people have each pulse, NEG, FLAT and POS (zero when
// none do); people whose pulse is "n/a" are not counted.
          <th scope="col">Drag</th>
          <th scope="col">Lift</th>
          <th scope="col">Yield</th>
          <th scope="col">Grip</th>
          <th scope="col">Charge</th>
          <th scope="col">Churn</th>
          <th scope="col">Norm</th>
          <th scope="col">Outlier</th>
          <th scope="col">Ebb</th>
          <th scope="col">Rank</th>
          <th scope="col">Percentile</th>
          <th scope="col">Set alpha</th>
          <th scope="col">Set beta</th>
  spool: number | null;
  drag: string | null;
  lift: number | null;
  yield: number | null;
  grip: number | null;
  charge: number | null;
  churn: number | null;
  norm: number | null;
  outlier: boolean;
  ebb: number | null;
}

// A sheet: its id (null for the unnamed sheet) and its anchor date (yyyy-mm-dd; today when none is set).
export interface Sheet {
  id: string | null;
  anchor: string;

